def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        marks = [i for i, value in enumerate(row) if value == 6]
        for left, right in zip(marks[::2], marks[1::2]):
            for col in range(left + 1, right):
                if row[col] == 0:
                    row[col] = 2
    return out

def transform(grid):
    out = [row[:] for row in grid]
    for row in out:
        marks = [i for i, value in enumerate(row) if value != 0]
        if len(marks) >= 2:
            for col in range(marks[0] + 1, marks[-1]):
                if row[col] == 0:
                    row[col] = 2
    return out
